{
  "name": "loja-api",
  "version": "1.3.0",
  "private": true,
  "type": "module",
  "description": "API de pedidos da Loja de exemplo",
  "scripts": {
    "start": "node src/server.js",
    "test": "node --test test/*.test.js"
  }
}
import { listarProdutos } from './produtos.js'
import { criarPedidos } from './pedidos.js'
import { criarFrete } from './frete/index.js'
import { ErroApi, corpoDeErro } from './erros.js'

// Rotas da API. handle() recebe método, caminho e corpo já lido, e devolve { status, body }:
// o server.js só traduz isso para HTTP, e os testes chamam handle() direto.
export function criarApp({ frete = criarFrete(), agora } = {}) {
  const pedidos = criarPedidos({ frete, agora })

  const rotas = [
    ['GET', /^\/produtos$/, () => ({ status: 200, body: { produtos: listarProdutos() } })],
    ['GET', /^\/pedidos$/, (_m, _b, q) => ({ status: 200, body: { pedidos: pedidos.listar({ status: q.get('status') ?? undefined }) } })],
    ['POST', /^\/pedidos$/, async (_m, b) => ({ status: 201, body: await pedidos.criar(b) })],
    ['GET', /^\/pedidos\/([\w-]+)$/, (m) => ({ status: 200, body: pedidos.obter(m[1]) })],
    ['POST', /^\/pedidos\/([\w-]+)\/cancelamento$/, (m, b) => ({ status: 200, body: pedidos.cancelar(m[1], b?.motivo) })]
  ]

  return {
    async handle(method, url, body) {
      const { pathname, searchParams } = new URL(url, 'http://loja.local')
      for (const [verbo, padrao, fn] of rotas) {
        const m = pathname.match(padrao)
        if (m && verbo === method) {
          try {
            return await fn(m, body, searchParams)
          } catch (e) {
            if (e instanceof ErroApi) return { status: e.status, body: corpoDeErro(e) }
            throw e
          }
        }
      }
      return { status: 404, body: corpoDeErro(new ErroApi(404, 'ROTA_INEXISTENTE', `${method} ${pathname} não existe`)) }
    }
  }
}
export class ErroApi extends Error {
  constructor(status, codigo, mensagem) {
    super(mensagem)
    this.status = status
    this.codigo = codigo
  }
}

export function corpoDeErro(e) {
  return { erro: { codigo: e.codigo, mensagem: e.message } }
}
import { obterProduto } from './produtos.js'
import { ErroApi } from './erros.js'

const CEP = /^\d{5}-?\d{3}$/

export function criarPedidos({ frete, agora = () => new Date() }) {
  const pedidos = new Map()
  let seq = 1000

  return {
    async criar(entrada) {
      if (!entrada || !Array.isArray(entrada.itens) || entrada.itens.length === 0) {
        throw new ErroApi(400, 'ITENS_OBRIGATORIOS', 'Informe ao menos um item')
      }
      if (typeof entrada.cep !== 'string' || !CEP.test(entrada.cep)) {
        throw new ErroApi(400, 'CEP_INVALIDO', 'CEP deve ter 8 dígitos')
      }
      let subtotal = 0
      let peso = 0
      const itens = entrada.itens.map((i) => {
        const produto = obterProduto(i.produtoId)
        if (!produto) throw new ErroApi(422, 'PRODUTO_INEXISTENTE', `Produto ${i.produtoId} não existe`)
        const quantidade = Number.isInteger(i.quantidade) && i.quantidade > 0 ? i.quantidade : 1
        subtotal += produto.precoCentavos * quantidade
        peso += produto.pesoGramas * quantidade
        return { produtoId: produto.id, quantidade, precoCentavos: produto.precoCentavos }
      })
      const cepDestino = entrada.cep.replace('-', '')
      let cotacao
      try {
        cotacao = await frete.cotar({ cepDestino, pesoGramas: peso })
      } catch (e) {
        throw new ErroApi(503, 'FRETE_INDISPONIVEL', e.message)
      }
      const id = `ped-${++seq}`
      const pedido = {
        id,
        status: 'aguardando_pagamento',
        itens,
        cep: cepDestino,
        subtotalCentavos: subtotal,
        freteCentavos: cotacao.valorCentavos,
        totalCentavos: subtotal + cotacao.valorCentavos,
        transportadora: cotacao.transportadora,
        criadoEm: agora().toISOString()
      }
      pedidos.set(id, pedido)
      return pedido
    },

    listar({ status } = {}) {
      return [...pedidos.values()].filter((p) => !status || p.status === status)
    },

    obter(id) {
      const p = pedidos.get(id)
      if (!p) throw new ErroApi(404, 'PEDIDO_NAO_ENCONTRADO', `Pedido ${id} não existe`)
      return p
    },

    cancelar(id, motivo) {
      const p = this.obter(id)
      if (p.status === 'enviado') throw new ErroApi(409, 'PEDIDO_JA_ENVIADO', 'Pedido já enviado não pode ser cancelado')
      p.status = 'cancelado'
      p.motivoCancelamento = motivo ?? null
      return p
    }
  }
}
// Catálogo em memória. Em produção vem do serviço de catálogo; aqui basta para a API de pedidos.
const PRODUTOS = [
  { id: 'p-100', nome: 'Caneca esmaltada', precoCentavos: 4990, pesoGramas: 350 },
  { id: 'p-200', nome: 'Garrafa térmica 1 L', precoCentavos: 12990, pesoGramas: 600 },
  { id: 'p-300', nome: 'Kit de talheres', precoCentavos: 7990, pesoGramas: 420 },
  { id: 'p-400', nome: 'Toalha de mesa', precoCentavos: 8990, pesoGramas: 800 }
]

export function listarProdutos() {
  return PRODUTOS.map((p) => ({ ...p }))
}

export function obterProduto(id) {
  const p = PRODUTOS.find((x) => x.id === id)
  return p ? { ...p } : undefined
}
import { createServer } from 'node:http'
import { criarApp } from './app.js'

const app = criarApp()
const porta = Number(process.env.PORT ?? 3000)

createServer(async (req, res) => {
  let texto = ''
  for await (const parte of req) texto += parte
  let corpo
  try {
    corpo = texto ? JSON.parse(texto) : undefined
  } catch {
    res.writeHead(400, { 'content-type': 'application/json' })
    return res.end(JSON.stringify({ erro: { codigo: 'JSON_INVALIDO', mensagem: 'Corpo não é JSON' } }))
  }
  const { status, body } = await app.handle(req.method, req.url, corpo)
  res.writeHead(status, { 'content-type': 'application/json' })
  res.end(JSON.stringify(body))
}).listen(porta, () => console.log(`loja-api em http://localhost:${porta}`))

